```python
import unittest
from hypothesis import given
from hypothesis import strategies as st
def reverse_list(lst):
    return lst[::-1]
class TestReverseList(unittest.TestCase):
    @given(st.lists(st.integers()))
    def test_double_reverse_is_identity(self, lst):
        """对任意整数列表：双重反转等于原列表"""
        self.assertEqual(reverse_list(reverse_list(lst)), lst)
    @given(st.lists(st.integers()))
    def test_length_preserved(self, lst):
        self.assertEqual(len(reverse_list(lst)), len(lst))
    @given(st.lists(st.integers(), min_size=1))
    def test_first_element_becomes_last(self, lst):
        result = reverse_list(lst)
        self.assertEqual(result[-1], lst[0])
        self.assertEqual(result[0], lst[-1])
```

`@given` 装饰器接受一个或多个**策略（strategy）**，Hypothesis 根据策略自动生成输入，默认生成 100 个用例。

`assume()` 用于过滤无效输入，而不是报错：

```python
from hypothesis import assume, given, settings
from hypothesis import strategies as st
class TestDivision(unittest.TestCase):
    @given(st.integers(), st.integers())
    def test_division_result(self, a, b):
        assume(b != 0)   # 跳过 b=0 的用例
        result = a / b
        self.assertAlmostEqual(result * b, a, places=10)
    @settings(max_examples=500)  # 生成更多用例，更彻底
    @given(st.integers())
    def test_thorough(self, n):
        self.assertIsInstance(n, int)
```

注意：`assume()` 过多会降低生成效率，优先用有界策略或 `.filter()`。`@settings(max_examples=10)` 可以在 CI 环境加快速度。

Hypothesis 找到失败用例时，会自动收缩到最简单的反例：

```python
def buggy_sort(lst):
    """有 bug 的排序：丢弃了负数"""
    return sorted(x for x in lst if x >= 0)
class TestBuggySort(unittest.TestCase):
    @given(st.lists(st.integers()))
    def test_sort_preserves_all_elements(self, lst):
        result = buggy_sort(lst)
        self.assertEqual(sorted(result), sorted(lst))
# Hypothesis 不会报告原始大列表，而是收缩到：
# Falsifying example: test_sort_preserves_all_elements(lst=[-1])
```

这是属性测试最有价值的特性之一——不只告诉你「失败了」，还告诉你「最简单的失败场景是什么」。

```python
from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Optional
@dataclass
class Order:
    id: int
    total: float
    user_email: str = ""
class OrderRepository(ABC):
    @abstractmethod
    def find_by_id(self, order_id: int) -> Optional[Order]: ...
class PaymentService(ABC):
    @abstractmethod
    def charge(self, order_id: int, amount: float) -> dict: ...
class OrderProcessor:
    PAYMENT_THRESHOLD = 1000.0
    def __init__(self, orders: OrderRepository,
                 payment: PaymentService, notifier):
        self._orders = orders
        self._payment = payment
        self._notifier = notifier
    def process(self, order_id: int):
        order = self._orders.find_by_id(order_id)
        if order is None:
            raise LookupError(f"Order {order_id} not found")
        payment_ref = None
        if order.total > self.PAYMENT_THRESHOLD:
            result = self._payment.charge(
                order_id=order.id, amount=order.total)
            payment_ref = result.get("ref")
        return ProcessResult(order_id=order_id, payment_ref=payment_ref)
```

Fake 优于 Mock：Fake 有真实的业务逻辑，可以暴露内部状态，更接近真实行为。

```python
class FakeOrderRepository(OrderRepository):
    def __init__(self):
        self._orders: dict = {}
    def save(self, order: Order) -> Order:
        self._orders[order.id] = order
        return order
    def find_by_id(self, order_id: int) -> Optional[Order]:
        return self._orders.get(order_id)
class FakePaymentService(PaymentService):
    def __init__(self):
        self.charges: list = []
        self._fail = False
    def charge(self, order_id: int, amount: float) -> dict:
        if self._fail:
            raise RuntimeError("Gateway down")
        ref = f"fake_{len(self.charges)+1}"
        self.charges.append({"order_id": order_id, "amount": amount})
        return {"ref": ref, "status": "ok"}
    def simulate_failure(self):
        self._fail = True
```

Fake 测试通过，但真实实现有 bug——这是六边形架构最常见的陷阱。契约测试（contract tests）防止这种情况：

```python
class OrderRepositoryContractTest:
    """抽象契约：所有 OrderRepository 实现都必须通过"""
    def get_repo(self) -> OrderRepository:
        raise NotImplementedError
    def test_find_saved_order(self):
        repo = self.get_repo()
        order = Order(id=1, total=100.0)
        repo.save(order)
        found = repo.find_by_id(1)
        self.assertIsNotNone(found)
        self.assertEqual(found.total, 100.0)
    def test_find_nonexistent_returns_none(self):
        repo = self.get_repo()
        self.assertIsNone(repo.find_by_id(9999))
class TestFakeOrderRepository(OrderRepositoryContractTest,
                               unittest.TestCase):
    def get_repo(self):
        return FakeOrderRepository()
```

同一套契约测试，Fake 跑一遍，真实实现也跑一遍，行为必须一致。

接缝是代码中**可以替换行为而不修改调用处**的地方。最常用的是对象接缝，通过依赖注入引入：

```python
# 原始遗留代码：硬编码依赖
class LegacyReportGenerator:
    def generate(self, report_id):
        conn = psycopg2.connect("host=legacy-prod user=app")  # 无法测试！
        ...
# 引入接缝：添加参数，默认值保持原有行为（向后兼容）
class LegacyReportGenerator:
    def __init__(self, db_conn=None, output_dir=None):
        self._db_conn = db_conn
        self._output_dir = output_dir or "/var/reports"
    def _get_connection(self):
        if self._db_conn:
            return self._db_conn   # 测试时注入
        return psycopg2.connect("host=legacy-prod user=app")  # 原有行为
    def generate(self, report_id):
        conn = self._get_connection()  # 接缝！
        ...
```

关键：默认值保持原有行为，生产代码调用处不需要修改。

绞杀者模式用新实现逐步替换旧实现，同时保持系统持续运行：

```python
# 新实现（TDD 驱动，有完整测试）
class DiscountCalculator:
    def calculate(self, price: float, user_type: str, quantity: int) -> float:
        discount = self._get_discount_rate(user_type, quantity)
        return price * (1 - discount)
    def _get_discount_rate(self, user_type: str, quantity: int) -> float:
        if user_type == "vip":
            return 0.20
        if quantity > 100:
            return 0.15
        return 0.0
# 过渡层：Feature flag 控制新旧切换
def calculate_discount(price, user_type, quantity, use_new=False):
    if use_new or os.environ.get("USE_NEW_DISCOUNT"):
        return DiscountCalculator().calculate(price, user_type, quantity)
    return legacy_calculate_discount(price, user_type, quantity)
```

用行为等价测试验证新旧实现对相同输入结果一致，再逐步切换流量。

Sprout 方法：不动遗留代码，把新逻辑单独实现、单独测试，再从遗留代码入口最小化调用：

```python
# 新增逻辑独立实现，有完整测试
def validate_payment_request(order_id: int, amount: float) -> None:
    if amount <= 0:
        raise ValueError(f"Amount must be positive: {amount}")
    if order_id <= 0:
        raise ValueError(f"Invalid order_id: {order_id}")
class TestValidatePaymentRequest(unittest.TestCase):
    def test_valid_request_passes(self):
        validate_payment_request(1, 100.0)  # 不抛出即通过
    def test_negative_amount_raises(self):
        with self.assertRaises(ValueError):
            validate_payment_request(1, -50.0)
# 在遗留代码入口处加一行调用（最小侵入）
def legacy_process_payment(order_id, amount, card_number):
    validate_payment_request(order_id, amount)  # 唯一新增的一行
    # ... 原有代码不动
```

`MagicMock` 可以访问任意属性而不报错，原理是 `__getattr__`：

```python
from unittest.mock import MagicMock
m = MagicMock()
# 访问任意属性 → 自动返回子 MagicMock
m.foo           # MagicMock（自动创建）
m.foo.bar       # MagicMock（链式）
# 重要：同一属性每次访问返回同一个对象（子 Mock 被缓存）
assert m.foo is m.foo   # True！
# 简化版原理
class SimpleMock:
    def __init__(self):
        self._children = {}
        self._calls = []
    def __getattr__(self, name):
        if name.startswith('_'):
            raise AttributeError(name)
        if name not in self._children:
            self._children[name] = SimpleMock()
        return self._children[name]
    def __call__(self, *args, **kwargs):
        self._calls.append((args, kwargs))
        return SimpleMock()
```

子 Mock 被缓存意味着 `m.charge.assert_called_once_with(...)` 访问到的是**同一个** `m.charge`，调用历史完整保留。

当 `pay()` 里有 `if method == "stripe" / "paypal" / "crypto"` 三个分支，每种都要 Mock 不同的库，测试越来越复杂。TDD 逼你问：Checkout 真正需要的是什么接口？

```python
class TestCheckout(unittest.TestCase):
    def test_pay_delegates_to_payment_strategy(self):
        # 测试只需要「一个可以执行支付的对象」
        mock_strategy = MagicMock()
        checkout = Checkout(payment_strategy=mock_strategy)
        checkout.pay(100.0)
        mock_strategy.execute.assert_called_once_with(100.0)
from abc import ABC, abstractmethod
class PaymentStrategy(ABC):
    @abstractmethod
    def execute(self, amount: float) -> dict: ...
class Checkout:
    def __init__(self, payment_strategy: PaymentStrategy):
        self._strategy = payment_strategy
    def pay(self, amount: float) -> dict:
        return self._strategy.execute(amount)
```

每种支付方式单独实现一个 Strategy，独立测试，Checkout 本身的测试从此简单干净。

Order 下单时需要发邮件、更新库存、记录分析——全写在 `place()` 里，每次添加新副作用都要修改 Order 类。TDD 迫使你想：我能不能只验证「Order 通知了什么」？

```python
class TestOrderPlacement(unittest.TestCase):
    def test_placing_order_notifies_observers(self):
        observer = MagicMock()  # 通用 Observer
        order = Order(items=["apple"], user_email="a@b.com")
        order.add_observer(observer)
        order.place()
        observer.on_order_placed.assert_called_once_with(order)
class OrderObserver(ABC):
    @abstractmethod
    def on_order_placed(self, order) -> None: ...
class Order:
    def add_observer(self, observer: OrderObserver) -> None:
        self._observers.append(observer)
    def place(self) -> None:
        self._save_to_db()
        for obs in self._observers:
            obs.on_order_placed(self)
```

`EmailNotifier`、`InventoryUpdater` 各自独立实现和测试，Order 本身不再关心通知细节。

要支持「撤销上一步操作」，操作必须是「可记录的」。TDD 直接逼出了这个需求：

```python
class TestTextEditorUndo(unittest.TestCase):
    def test_undo_insert(self):
        editor = TextEditor()
        editor.execute(InsertCommand(pos=0, text="Hello"))
        editor.undo()
        self.assertEqual(editor.content, "")
class Command(ABC):
    @abstractmethod
    def execute(self, content: str) -> str: ...
    @abstractmethod
    def undo(self, content: str) -> str: ...
class InsertCommand(Command):
    def __init__(self, pos: int, text: str):
        self.pos = pos
        self.text = text
    def execute(self, content: str) -> str:
        return content[:self.pos] + self.text + content[self.pos:]
    def undo(self, content: str) -> str:
        return content[:self.pos] + content[self.pos + len(self.text):]
```

每个 Command 独立测试 `execute` 和 `undo`，TextEditor 只管维护 history 和 redo_stack。

每个测试都要构造一个有十个字段的 User，但只关心 `role` 字段，代码非常啰嗦。Builder 提供合理默认值，让测试只写关心的字段：

```python
class UserBuilder:
    def __init__(self):
        self._data = {
            "id": 1, "name": "Test User",
            "email": "test@example.com",
            "role": "normal", "active": True
        }
    def as_vip(self) -> 'UserBuilder':
        self._data["role"] = "vip"
        return self
    def inactive(self) -> 'UserBuilder':
        self._data["active"] = False
        return self
    def build(self) -> User:
        return User(**self._data)
class TestUserDiscount(unittest.TestCase):
    def test_vip_gets_20_percent_discount(self):
        user = UserBuilder().as_vip().build()  # 只关心 role！
        self.assertAlmostEqual(calculate_discount(user), 0.2)
    def test_inactive_user_no_discount(self):
        user = UserBuilder().inactive().build()
        self.assertAlmostEqual(calculate_discount(user), 0.0)
```
